<script lang="ts">
 import {invoke} from '@tauri-apps/api/core';
 import {romeToUtc} from './rome.js';
 import sectors from '../content/lazio-sectors.v1.json';
 import ForecastView from './ForecastView.svelte';
 type Scenario={forecast_snapshot:Record<string,unknown>|null,technique:string,condition:string,condition_origin:string,fixed_rig:string|null,casting_limit_g:number|null,location:string,start_at:string,end_at:string,target:string};
 type Recommendation={rig_id:string,reason:string,risk:string,check:string,source:string,evidence:string};
 type Evaluation={recommendations:Recommendation[],warnings:string[],engine_version:string,content_version:string};
 type Saved={id:number,created_at:string,scenario_json:string,result_json:string,engine_version:string,content_version:string};
 export let forecastReference:Record<string,unknown>|null=null;
 let attachForecast=false;
 let technique='fondo',condition='sconosciuto',origin='simulazione',fixed='',limit='',location='',start='',end='',target='',error='',notice='';
 let result:Evaluation|null=null;let plans:Saved[]=[];let selected:Saved|null=null;let savedScenario:Scenario|null=null;
 function asUtc(s:string){return romeToUtc(s)}
 function input():Scenario {if(!start||!end)throw new Error('Inserisci inizio e fine della finestra.');return {forecast_snapshot:attachForecast ? forecastReference : null,technique,condition,condition_origin:origin,fixed_rig:fixed||null,casting_limit_g:limit?Number(limit):null,location,start_at:asUtc(start),end_at:asUtc(end),target}}
 function message(e:unknown){return typeof e==='object'&&e!==null&&'message' in e?String(e.message):'Impossibile valutare lo scenario.'}
 async function evaluate(){try{result=await invoke('evaluate_scenario',{scenario:input()});error='';notice='';selected=null;savedScenario=null}catch(e){error=message(e);result=null}}
 async function save(){try{result=await invoke('save_plan',{scenario:input()});error='';selected=null;savedScenario=null;notice='Piano salvato con la versione delle regole.';await load()}catch(e){error=message(e)}}
 async function load(){try{plans=await invoke('list_plans')}catch{}}
 function show(plan:Saved){selected=plan;savedScenario=JSON.parse(plan.scenario_json) as Scenario;result=JSON.parse(plan.result_json) as Evaluation;notice='Stai leggendo il risultato salvato; le scelte nel modulo non sono state modificate.';}
 import {onMount} from 'svelte';onMount(load);
</script>
<div class="planner"><h2>Confronta uno scenario</h2><p>Gli orari sono riferiti a Roma. Indica le condizioni osservate o prova una simulazione. Le regole sono suggerimenti operativi iniziali, non previsioni di cattura.</p><form class="planner-grid" on:submit|preventDefault={evaluate}><label>Inizio<input type="datetime-local" bind:value={start} required></label><label>Fine<input type="datetime-local" bind:value={end} required></label><label>Settore della ricerca<select bind:value={location}><option value="">Seleziona un settore</option>{#each sectors.sectors as sector}<option value={sector.id}>{sector.name}</option>{/each}</select></label><label>Specie desiderata <span>facoltativo, solo annotazione</span><input bind:value={target}></label><label>Tecnica<select bind:value={technique}><option value="fondo">Pesca a fondo</option><option value="bolognese">Bolognese</option></select></label><label>Condizioni<select bind:value={condition}><option value="sconosciuto">Non conosciute</option><option value="calmo">Mare calmo / corrente contenuta</option><option value="mosso_lavorabile">Moto ondoso lavorabile</option><option value="corrente_moderata">Corrente moderata</option></select></label><label>Origine delle condizioni<select bind:value={origin}><option value="simulazione">Simulazione</option><option value="osservazione">Osservazione personale</option></select></label><label>Montatura fissata<select bind:value={fixed}><option value="">Qualsiasi</option>{#each ['A','B','C','D','E','F'] as rig}<option value={rig}>{rig}</option>{/each}</select></label><label>Potenza massima canna in g <span>facoltativo</span><input type="number" min="0.1" step="0.1" bind:value={limit}></label>{#if forecastReference}<label class="forecast-opt"><input type="checkbox" bind:checked={attachForecast}> Allega l’ultima risposta meteo/mare al piano, come riferimento</label>{/if}<div class="planner-buttons"><button class="primary" type="submit">Valuta scenario</button><button class="secondary" type="button" on:click={save}>Salva piano</button></div></form>{#if error}<p class="error" role="alert">{error}</p>{/if}{#if notice}<p class="notice" role="status">{notice}</p>{/if}
{#if result}<section class="plan-results"><h3>{selected && notice.startsWith('Stai') ? 'Risultato salvato' : 'Proposte da verificare'}</h3>{#if selected && savedScenario}<p>Finestra: {new Intl.DateTimeFormat('it-IT',{dateStyle:'short',timeStyle:'short',timeZone:'Europe/Rome'}).format(new Date(savedScenario.start_at))} – {new Intl.DateTimeFormat('it-IT',{dateStyle:'short',timeStyle:'short',timeZone:'Europe/Rome'}).format(new Date(savedScenario.end_at))}. Tecnica: {savedScenario.technique}. Condizioni: {savedScenario.condition.replaceAll('_',' ')} ({savedScenario.condition_origin}). Settore: {sectors.sectors.find(s => s.id === savedScenario?.location)?.name || 'non indicato'}. Specie: {savedScenario.target || 'non indicata'}. Risposta meteo/mare allegata: {savedScenario.forecast_snapshot ? 'sì' : 'no'}. Montatura fissata: {savedScenario.fixed_rig || 'nessuna'}; potenza massima canna: {savedScenario.casting_limit_g ? `${savedScenario.casting_limit_g} g` : 'non indicata'}.</p>{#if savedScenario.forecast_snapshot}<details><summary>Condizioni meteo e mare conservate</summary><ForecastView snapshot={savedScenario.forecast_snapshot} /></details>{/if}{/if}{#each result.recommendations as item}<article><strong>Montatura {item.rig_id}</strong><p>{item.reason}</p><p><b>Limite:</b> {item.risk}</p><p><b>Controllo:</b> {item.check}</p><p class="source">Evidenza {item.evidence}. {item.source}</p></article>{/each}{#each result.warnings as warning}<p class="plan-warning">{warning}</p>{/each}<p class="source">Motore {result.engine_version}; contenuti {result.content_version}. Il settore limita la ricerca all’area documentata; habitat preciso e specie sono ancora da verificare e non influenzano la selezione. Le condizioni non sono previsioni automatiche; un’eventuale risposta allegata non influenza le regole e può non coprire la finestra scelta.</p></section>{/if}
{#if plans.length}<details><summary>Piani salvati ({plans.length})</summary><p>Le valutazioni restano quelle mostrate al momento del salvataggio.</p>{#each plans as plan}<button class="saved-plan" on:click={() => show(plan)}>Piano {plan.id} · {plan.created_at} UTC</button>{/each}</details>{/if}</div>
